#define MAX_METRICS 100
#define MAX_METRIC_NAME_LENGTH 256

static char monitoring_metrics[MAX_METRICS][MAX_METRIC_NAME_LENGTH];
static int metric_count = 0;

int add_monitoring_metric(const char* metric_name) {
    // 检查输入参数是否有效
    if (metric_name == NULL) {
        return -1; // 参数无效
    }

    // 检查指标名称长度
    size_t name_len = strlen(metric_name);
    if (name_len == 0 || name_len >= MAX_METRIC_NAME_LENGTH) {
        return -2; // 名称长度无效
    }

    // 验证指标名称格式：只允许字母、数字、下划线和点号
    for (size_t i = 0; i < name_len; i++) {
        char c = metric_name[i];
        if (!((c >= 'a' && c <= 'z') || 
              (c >= 'A' && c <= 'Z') || 
              (c >= '0' && c <= '9') || 
              c == '_' || c == '.')) {
            return -3; // 名称格式无效
        }
    }

    // 检查是否已存在相同的指标名称
    for (int i = 0; i < metric_count; i++) {
        if (strcmp(monitoring_metrics[i], metric_name) == 0) {
            return -4; // 指标名称已存在
        }
    }

    // 检查是否达到最大指标数量限制
    if (metric_count >= MAX_METRICS) {
        return -5; // 达到最大指标数量限制
    }

    // 将指标名称复制到监控配置中
    strncpy(monitoring_metrics[metric_count], metric_name, MAX_METRIC_NAME_LENGTH - 1);
    monitoring_metrics[metric_count][MAX_METRIC_NAME_LENGTH - 1] = '\0'; // 确保字符串结束符

    metric_count++; // 增加指标计数

    return 0; // 成功添加指标
}
